"""Two deeper lessons for every published subject in the catalogue.

The breadth pass (``subject_paths.STARTERS``) gave every subject one starter
lesson. This module is the depth pass: every subject - without exception -
gains two more lessons that push past the entry point into the relations an
engineer actually calculates with, each with a governing formula, a derivation
sketch, a worked example with checkable arithmetic, applications, a real
pitfall and an industry-practice note.

Honesty rules this file follows:

* Every lesson is synthesised into the standard 13-section note by
  ``subject_paths._build_topic`` and carries ``accuracy_state="needs_review"``:
  published and reachable, but flagged as starter material, not expert
  sign-off.
* Formulas are canonical relations of the field with their validity conditions
  stated, not decorative equations. Non-quantitative subjects use an explicit
  rubric in place of a physical law and say so.
* Worked examples use round numbers so a learner can reproduce every step by
  hand; the answer stated is the answer the steps produce.
* Lesson titles must not collide with any existing topic title - the pipeline
  raises on duplicate slugs, and ``validate()`` here re-checks the spec shape
  before the seed ever touches the database.
"""
from __future__ import annotations


def _f(name: str, latex: str, variables: tuple[tuple[str, str, str], ...], conditions: str) -> dict:
    return {
        "name": name,
        "latex": latex,
        "variables": [{"s": symbol, "n": meaning, "u": unit} for symbol, meaning, unit in variables],
        "conditions": conditions,
    }


def _e(problem: str, approach: str, solution: str, answer: str) -> dict:
    return {"problem": problem, "approach": approach, "solution": solution, "answer": answer}


def _lesson(
    title: str,
    focus: str,
    formula: dict,
    derivation: str,
    example: dict,
    applications: tuple[str, str],
    pitfall: str,
    industry: str,
    *,
    tags: tuple[str, ...] = (),
    difficulty: str = "medium",
    minutes: int = 30,
) -> dict:
    return {
        "title": title,
        "focus": focus,
        "formula": formula,
        "derivation": derivation,
        "example": example,
        "applications": list(applications),
        "pitfall": pitfall,
        "industry": industry,
        "tags": list(tags),
        "difficulty": difficulty,
        "minutes": minutes,
        "quiz": None,
        "diagram_steps": None,
    }


#: Every subject must gain at least this many deeper lessons - "leave nothing"
#: is enforced by validate(), not by hope.
MIN_LESSONS_PER_SUBJECT = 2

_REQUIRED_FIELDS = ("title", "focus", "formula", "derivation", "example", "applications",
                    "pitfall", "industry", "tags", "difficulty", "minutes")


