def validate(subject_slugs: set[str]) -> None:
    """Fail the seed if the depth pass does not actually cover every subject.

    Collects all problems so one run names every gap instead of one per reseed.
    """
    problems: list[str] = []
    unknown = sorted(set(LESSONS) - subject_slugs)
    if unknown:
        problems.append(f"deeper lessons reference unknown subjects: {unknown}")
    missing = sorted(subject_slugs - set(LESSONS))
    if missing:
        problems.append(f"subjects with no deeper lessons: {missing}")
    for slug, specs in LESSONS.items():
        if len(specs) < MIN_LESSONS_PER_SUBJECT:
            problems.append(f"{slug}: {len(specs)} deeper lessons, at least {MIN_LESSONS_PER_SUBJECT} required")
        for spec in specs:
            title = spec.get("title", "")
            for field in _REQUIRED_FIELDS:
                if not spec.get(field):
                    problems.append(f"{slug} / {title!r}: missing field {field!r}")
            if len(spec.get("applications", [])) != 2:
                problems.append(f"{slug} / {title!r}: needs exactly two applications")
            if spec.get("difficulty") not in ("easy", "medium", "hard"):
                problems.append(f"{slug} / {title!r}: difficulty must be easy/medium/hard")
            formula = spec.get("formula") or {}
            if not formula.get("name") or not formula.get("latex") or not formula.get("variables"):
                problems.append(f"{slug} / {title!r}: formula needs name, latex and variables")
            example = spec.get("example") or {}
            for field in ("problem", "approach", "solution", "answer"):
                if not example.get(field):
                    problems.append(f"{slug} / {title!r}: example missing {field!r}")
    titles = [spec["title"] for specs in LESSONS.values() for spec in specs]
    duplicates = sorted({title for title in titles if titles.count(title) > 1})
    if duplicates:
        problems.append(f"duplicate deeper-lesson titles: {duplicates}")
    if problems:
        raise ValueError("deeper_lessons.py does not satisfy the coverage contract:\n  " + "\n  ".join(problems))
